"""Deepgram ASR engine — shared constants.

Keeping constants in their own module avoids circular imports between
:mod:`config` (which needs ``V2_MODEL_PREFIXES`` in its discriminator)
and :mod:`_v2` (which uses the same set for routing logic).
"""

from typing_extensions import Literal

# API version literals — used as Pydantic field defaults and in runtime comparisons.
DEEPGRAM_API_V1: Literal["v1"] = "v1"
DEEPGRAM_API_V2: Literal["v2"] = "v2"

# Explicit set of model-name prefixes that use the v2 (/v2/listen) API.
# All other Deepgram model names use v1 (/v1/listen).
# Add a new entry here when Deepgram ships a second v2 model family.
V2_MODEL_PREFIXES: frozenset[str] = frozenset({"flux-"})

# --------------------------------------------------------------------------- #
# Default API endpoint
# --------------------------------------------------------------------------- #

DEFAULT_ENDPOINT = "api.deepgram.com"

# --------------------------------------------------------------------------- #
# v1 (Nova) defaults
# --------------------------------------------------------------------------- #

DEFAULT_V1_MODEL = "nova-3"
DEFAULT_V1_ENDPOINTING = 400
DEFAULT_V1_SMART_FORMAT = True
DEFAULT_V1_UTTERANCE_END_MS = 1000

# --------------------------------------------------------------------------- #
# v2 (Flux) defaults
# --------------------------------------------------------------------------- #

DEFAULT_V2_MODEL = "flux-general-en"
